UPDATE finance_receipt_credit SET voucher_reference=#{voucherReference},entry_reference=#{entryReference},supplier_adjustment_id=#{id},supplier_adjustment_version=#{version}
WHERE tenant_id=#{tenantId} AND legal_entity_id=#{legalEntityId} AND business_id=#{requestId} AND channel='BANK_TRANSFER' AND transaction_reference=#{transactionReference}
    AND supplier_registration_id=#{registrationId} AND amount=#{amount} AND currency=#{currency} AND voucher_reference IS NULL AND entry_reference IS NULL
    AND supplier_adjustment_id IS NULL AND supplier_adjustment_version IS NULL
